<script setup>
import {ref,onMounted,computed} from 'vue'
const props=defineProps({apiWrite:Function})
const rows=ref([]),form=ref(null),tagsText=ref(''),error=ref(''),busy=ref(false),loading=ref(true),search=ref('')
const siteUrl=(import.meta.env.VITE_SITE_URL||'http://localhost:5173').replace(/\/$/,'')
const categories=computed(()=>[...new Set(rows.value.map(p=>p.category).filter(Boolean))])
const filtered=computed(()=>rows.value.filter(p=>(p.title+' '+p.category+' '+p.tags.join(' ')).toLowerCase().includes(search.value.toLowerCase())))
async function load(){rows.value=await props.apiWrite('/api/admin/posts','GET')}
function edit(row){error.value='';form.value=row?JSON.parse(JSON.stringify(row)):{title:'',slug:'',excerpt:'',content:'',category:'',tags:[],cover_url:'',published:false};tagsText.value=form.value.tags.join(', ')}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{form.value=await props.apiWrite('/api/admin/posts'+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',{...form.value,tags:tagsText.value.split(',').map(t=>t.trim()).filter(Boolean)});await load();form.value=null}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(row){if(!confirm('Удалить статью «'+row.title+'»?'))return;busy.value=true;error.value='';try{await props.apiWrite('/api/admin/posts/'+row.id,'DELETE');await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function upload(event){const file=event.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{const body=new FormData();body.append('file',file);const response=await fetch('/api/uploads',{method:'POST',headers:{'x-admin-key':sessionStorage.getItem('nova_admin_key')||''},body});const data=await response.json();if(!response.ok)throw Error(data.error||'Ошибка загрузки');form.value.cover_url=data.url}catch(e){error.value=e.message}finally{busy.value=false;event.target.value=''}}
onMounted(async()=>{try{await load()}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template>
<div><div class="page-title"><div><span class="eyebrow">ПУБЛИКАЦИИ</span><h1>Блог</h1><p>Статьи, рубрики и теги.</p></div><button class="primary-btn" :disabled="busy" @click="edit()">＋ Создать статью</button></div><p v-if="error" class="alert" role="alert">{{error}}</p>
<div class="panel"><div class="panel-heading"><h2>Статьи ({{rows.length}})</h2><input v-model="search" class="search-input" placeholder="Поиск по названию, рубрике, тегу" aria-label="Поиск статей"></div><p v-if="loading" class="empty">Загрузка…</p><div v-else class="table-scroll"><table><thead><tr><th>Статья</th><th>Рубрика</th><th>Статус</th><th>Действия</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><strong>{{row.title}}</strong><div><a v-if="row.published" :href="siteUrl+'/blog/'+row.slug" target="_blank" rel="noopener">/blog/{{row.slug}}</a><span v-else>/blog/{{row.slug}}</span></div></td><td>{{row.category || '—'}}</td><td>{{row.published?'Опубликована':'Черновик'}}</td><td><button class="row-btn" :disabled="busy" @click="edit(row)">Изменить</button><button class="row-btn danger" :disabled="busy" @click="remove(row)">Удалить</button></td></tr></tbody></table><p v-if="!filtered.length" class="empty">Статьи не найдены.</p></div></div>
<div v-if="form" class="modal-backdrop"><div class="modal blog-modal"><div class="modal-heading"><h2>{{form.id?'Редактирование статьи':'Новая статья'}}</h2><button :disabled="busy" @click="form=null">×</button></div><form @submit.prevent="save"><fieldset :disabled="busy"><label>Заголовок<input v-model="form.title" maxlength="200" required></label><label>Адрес статьи<input v-model="form.slug" maxlength="120" required pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="first-post"><small>/blog/first-post — латинские буквы, цифры и дефисы</small></label><label>Краткое описание<textarea v-model="form.excerpt" maxlength="1000" rows="3"></textarea></label><label>Текст статьи<textarea v-model="form.content" maxlength="100000" rows="14"></textarea><small>Обычный текст с сохранением абзацев.</small></label><label>Рубрика<input v-model="form.category" maxlength="100" list="blog-categories"><datalist id="blog-categories"><option v-for="category in categories" :key="category" :value="category"></option></datalist></label><label>Теги через запятую<input v-model="tagsText" maxlength="1300" placeholder="Новости, Разработка"><small>До 20 уникальных тегов.</small></label><label>Обложка<input type="file" accept="image/jpeg,image/png,image/webp" @change="upload"><small>JPG, PNG, WebP до 5 МБ.</small></label><div v-if="form.cover_url"><img :src="form.cover_url" class="cover-preview" alt="Обложка"><button type="button" class="row-btn" @click="form.cover_url=''">Убрать обложку</button></div><label class="publish-check"><input type="checkbox" v-model="form.published"> Опубликована</label><p v-if="error" class="alert">{{error}}</p><div class="modal-actions"><button type="button" class="cancel-btn" @click="form=null">Отмена</button><button class="primary-btn">{{busy?'Сохранение…':'Сохранить'}}</button></div></fieldset></form></div></div>
</div>
</template>
<style scoped>
.blog-modal{width:min(760px,100%);}fieldset{border:0;padding:0;display:grid;gap:17px;min-width:0;} .cover-preview{display:block;max-width:100%;max-height:200px;object-fit:contain;margin-bottom:10px;}.publish-check{flex-direction:row;align-items:center;}td div{margin-top:8px;}td a{color:#287253;}
</style>
